use vstd::prelude::*;

verus! {

    // A simple function that returns 1.0 when i == j and 0.0 otherwise.
    fn diag_val(i: int, j: int) -> (result: f64)
        ensures
            result == if i == j { 1.0 } else { 0.0 },
    {
        if i == j {
            1.0
        } else {
            0.0
        }
    }

    // Builds the n×n identity matrix of f64s.
    fn identity(n: usize) -> (result: Vec<Vec<f64>>)
        ensures
            // Exactly n rows
            result.len() == n,
            // Each row has length n
            forall<r: usize> r < n ==> result[r].len() == n,
            // Matrix property: entry (i,j) == diag_val(i,j)
            forall<i: usize, j: usize> i < n && j < n ==>
                result[i][j] == diag_val(i as int, j as int),
    {
        let mut m: Vec<Vec<f64>> = Vec::with_capacity(n);
        let mut i: usize = 0;
        while i < n
            invariant
                // outer loop runs from 0..n
                i <= n,
                // we've built exactly i rows so far
                m.len() == i,
                // each built row k satisfies the identity‐matrix property
                forall<k: usize> k < i ==>
                    m[k].len() == n
                    && forall<j: usize> j < n ==>
                        m[k][j] == diag_val(k as int, j as int),
            decreases n - i,
        {
            // build the i-th row
            let mut row: Vec<f64> = Vec::with_capacity(n);
            let mut j: usize = 0;
            while j < n
                invariant
                    // inner loop runs from 0..n
                    j <= n,
                    // row has length j so far
                    row.len() == j,
                    // each built entry satisfies diag_val
                    forall<k: usize> k < j ==>
                        row[k] == diag_val(i as int, k as int),
                decreases n - j,
            {
                row.push(diag_val(i as int, j as int));
                j += 1;
            }
            m.push(row);
            i += 1;
        }
        m
    }

} // end verus!

